export class StopFrameworkPriorityManager {
  constructor(metricsCollector, taskRegistry) {
    this.metricsCollector = metricsCollector;
    this.taskRegistry = taskRegistry;
  }

  rankTasks() {
    const metrics = this.metricsCollector.collectMetrics();
    const rankedTasks = this.taskRegistry.map(task => {
      const impactScore = this.calculateImpactScore(task, metrics);
      return { task, impactScore };
    });

    return rankedTasks.sort((a, b) => b.impactScore - a.impactScore);
  }

  calculateImpactScore(task, metrics) {
    const capabilityGap = metrics.capabilityGaps[task.id] || 0;
    const systemImpact = task.estimatedImpact || 0;
    return capabilityGap * systemImpact;
  }

  prioritizeTasks() {
    const rankedTasks = this.rankTasks();
    return rankedTasks.map(entry => entry.task);
  }
}